import { randomBytes } from "node:crypto";
import { z } from "zod";

const supabaseStatusSchema = z.object({
  API_URL: z.url(),
  ANON_KEY: z.string().min(1),
  SERVICE_ROLE_KEY: z.string().min(1),
});

export function renderEnvLocal(statusJson: string, existingSalt: string | undefined): string {
  const status = supabaseStatusSchema.parse(JSON.parse(statusJson));
  const salt = existingSalt && existingSalt.length >= 16 ? existingSalt : randomBytes(16).toString("hex");
  return [
    "# Generated by pnpm env:local from `supabase status`. Local-only; never commit.",
    `NEXT_PUBLIC_SUPABASE_URL=${status.API_URL}`,
    `NEXT_PUBLIC_SUPABASE_ANON_KEY=${status.ANON_KEY}`,
    `SUPABASE_SERVICE_ROLE_KEY=${status.SERVICE_ROLE_KEY}`,
    `RATE_LIMIT_SALT=${salt}`,
    "NEXT_PUBLIC_SENTRY_DSN=",
    "",
  ].join("\n");
}
